-- supabase/seed.sql
--
-- Run this ONCE after schema.sql, to populate the table with the
-- catalog this project shipped with (same products/slides/texts you've
-- already been testing on the site). The admin panel will overwrite
-- these rows as soon as you publish any change from /admin.
--
-- NOTE: if you've already run this once and edited content via the
-- admin panel, DO NOT re-run this — it will overwrite those edits.
-- For adding new keys later without overwriting, use a targeted
-- migration like supabase/add-cart-keys.sql instead.

insert into site_data (key, value) values ('products', '[{"id": 1, "brand": "Tom Ford", "name": "Oud Wood", "size": "50 ml", "price": 380, "country": "USA", "availability": "in-stock", "image": "https://images.unsplash.com/photo-1774682060997-f8959850a7d4?w=500&h=600&fit=crop&auto=format", "description": {"en": "Rare oud wood blended with rosewood, cardamom and Chinese pepper.", "ru": "Редкое дерево уда в сочетании с розовым деревом, кардамоном и китайским перцем."}, "notes": {"en": "Oud · Rosewood · Amber", "ru": "Уд · Розовое дерево · Амбра"}}, {"id": 2, "brand": "Creed", "name": "Aventus", "size": "100 ml", "price": 520, "country": "France", "availability": "in-stock", "image": "https://images.unsplash.com/photo-1780943004195-3bd30f748872?w=500&h=600&fit=crop&auto=format", "description": {"en": "Fruity pineapple opening over birch, musk and ambergris — the fragrance of kings.", "ru": "Фруктовое открытие с ананасом на фоне берёзы, мускуса и амбры — аромат королей."}, "notes": {"en": "Pineapple · Birch · Musk", "ru": "Ананас · Берёза · Мускус"}}, {"id": 3, "brand": "Amouage", "name": "Interlude Man", "size": "100 ml", "price": 340, "country": "UAE", "availability": "in-stock", "image": "https://images.unsplash.com/photo-1771762013405-ad64577dfc55?w=500&h=600&fit=crop&auto=format", "description": {"en": "A complex odyssey of oregano, frankincense and oud — intensity meets sophistication.", "ru": "Сложная одиссея из орегано, ладана и уда — интенсивность встречается с изысканностью."}, "notes": {"en": "Oregano · Frankincense · Oud", "ru": "Орегано · Ладан · Уд"}}, {"id": 4, "brand": "Chanel", "name": "N°5 L''Eau", "size": "50 ml", "price": 185, "country": "France", "availability": "in-stock", "image": "https://images.unsplash.com/photo-1774682060992-46c7e9f2e50b?w=500&h=600&fit=crop&auto=format", "description": {"en": "A luminous reinvention of the iconic N°5, lighter and more vibrant than ever before.", "ru": "Светлое переосмысление культового N°5 — легче и ярче, чем